#!/usr/bin/env python3
"""Write the bilingual CLI pages from argparse. ``--check`` fails when they drift."""

from __future__ import annotations

import argparse
import os
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PAGES = {
    "en": ROOT / "docs" / "en" / "cli.md",
    "zh-CN": ROOT / "docs" / "zh-CN" / "cli.md",
}
TITLES = {
    "en": "CLI reference",
    "zh-CN": "命令行参考",
}
INTROS = {
    "en": "Generated by `scripts/build_cli_reference.py`. Do not edit by hand.",
    "zh-CN": "由 `scripts/build_cli_reference.py` 生成。不要手改。",
}


def _dump(parser) -> str:
    import argparse as argparse_mod

    chunks = [parser.format_help().rstrip()]
    for action in parser._actions:
        if not isinstance(action, argparse_mod._SubParsersAction):
            continue
        for _name, sub in action.choices.items():
            chunks.append(sub.format_help().rstrip())
            for nested in sub._actions:
                if isinstance(nested, argparse_mod._SubParsersAction):
                    for _child, leaf in nested.choices.items():
                        chunks.append(leaf.format_help().rstrip())
    return "\n\n".join(chunks) + "\n"


def render(language: str) -> str:
    os.environ["COLUMNS"] = "100"
    from barrett_faceswap.cli import build_parser
    from barrett_faceswap.i18n import set_language

    set_language(language)
    body = _dump(build_parser())
    return f"# {TITLES[language]}\n\n{INTROS[language]}\n\n```text\n{body}```\n"


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Generate docs/en/cli.md and docs/zh-CN/cli.md.")
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args(argv)
    drifted = []
    for language, path in PAGES.items():
        text = render(language)
        # argparse help can contain a trailing space that YAML would not care about.
        # Keep the bytes stable by normalizing newlines.
        text = text.replace("\r\n", "\n")
        if args.check:
            current = path.read_text(encoding="utf-8") if path.is_file() else ""
            if current != text:
                drifted.append(str(path.relative_to(ROOT)))
            continue
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
    if drifted:
        print("CLI reference drift: " + ", ".join(drifted), file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
